var body = msg.payload;
if (typeof body === 'string') {
    body = JSON.parse(body);
}
if (!body.device || !body.action) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'device dan action wajib diisi'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return [msg, null];
}

// Publish perintah ke MQTT
var mqttMsg = {payload: body, topic: 'iot/kontrol'};
return [Object.assign(msg, {
    statusCode: 200,
    payload: {status: 'success', message: 'Perintah terkirim', sent: body},
    headers: {'Access-Control-Allow-Origin': '*'}
}), mqttMsg];
